SELECT c.* FROM one_off_commitments c
 WHERE c.commitment_id = #{commitmentId}
   AND c.user_id = #{userId}
   AND c.is_deleted = 0

SELECT c.* FROM one_off_commitments c
 WHERE c.commitment_id = #{commitmentId}
   AND c.user_id = #{userId}
   AND c.is_deleted = 0
 FOR UPDATE

SELECT c.* FROM one_off_commitments c
 WHERE c.user_id = #{userId}
   AND c.is_deleted = 0
   AND c.start_at < #{rangeEnd}
   AND c.end_at   > #{rangeStart}
 ORDER BY c.start_at, c.commitment_id

mapper.update:
UPDATE one_off_commitments
   SET title         = #{title},
       start_at      = #{startAt},
       end_at        = #{endAt},
       location_text = #{locationText},
       version       = version + 1
 WHERE commitment_id = #{commitmentId}
   AND user_id = #{userId}
   AND version = #{version}
   AND is_deleted = 0

UPDATE one_off_commitments
   SET is_deleted = 1,
       derived_from_commitment_id = NULL,
       derived_relation           = NULL,
       version    = version + 1
 WHERE commitment_id = #{commitmentId}
   AND user_id = #{userId}
   AND version = #{version}
   AND is_deleted = 0

